inputs = ['xbcvu', 'wc', 'uybfh', 'ad', 'ekg']
outputs = ['dxbcvfy', 'wc', 'fyybfay', 'ad', 'eki']

for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input:  '{inp}' (length {len(inp)})")
    print(f"Output: '{out}' (length {len(out)})")
    if len(inp) == len(out):
        for j, (c_in, c_out) in enumerate(zip(inp, out)):
            if c_in != c_out:
                print(f"  Pos {j}: '{c_in}' → '{c_out}'")
    elif len(inp) < len(out):
        print("  Length increased")
        # Compare up to min length
        for j, (c_in, c_out) in enumerate(zip(inp, out[:len(inp)])):
            if c_in != c_out:
                print(f"  Pos {j}: '{c_in}' → '{c_out}'")
        # Show extra chars
        if len(out) > len(inp):
            print(f"  Extra chars at end: '{out[len(inp):]}'")
    else:
        print("  Length decreased")
        # Compare up to min length
        for j, (c_in, c_out) in enumerate(zip(inp[:len(out)], out)):
            if c_in != c_out:
                print(f"  Pos {j}: '{c_in}' → '{c_out}'")
        # Show removed chars
        if len(inp) > len(out):
            print(f"  Removed chars: '{inp[len(out):]}'")
    print()

